// ── Router: detecta el tipo de payload de Slack ──
// Slack envía 3 tipos:
//   1. url_verification: challenge inicial (JSON body)
//   2. block_actions: click en un botón (payload= form-urlencoded con campo 'payload')
//   3. view_submission: submit de modal (payload= form-urlencoded con campo 'payload')
//   4. event_callback: mensaje en canal (Events API, JSON body) — ignorado en esta versión

const raw = $input.first().json;
let body = null;

// Caso 1: body directo como JSON
if (raw.type) body = raw;
// Caso 2: body anidado en raw.body como objeto
else if (raw.body && typeof raw.body === 'object' && (raw.body.type || raw.body.payload)) body = raw.body;
// Caso 3: body anidado en raw.body como string
else if (raw.body && typeof raw.body === 'string') {
  try { body = JSON.parse(raw.body); } catch(e) {}
}
// Fallback
if (!body) body = raw;

// ── url_verification (challenge) ──
if (body.type === 'url_verification') {
  return [{ json: { route: 'challenge', challenge: body.challenge || '' } }];
}

// ── block_actions / view_submission llegan como form-urlencoded con campo 'payload' ──
let payload = null;
if (body.payload) {
  try {
    payload = typeof body.payload === 'string' ? JSON.parse(body.payload) : body.payload;
  } catch(e) {}
}

if (payload) {
  // ── Click en botón ──
  if (payload.type === 'block_actions') {
    const action  = (payload.actions && payload.actions[0]) || {};
    const codigo  = action.value || '';
    const userId  = (payload.user && payload.user.id) || '';
    const userName= (payload.user && (payload.user.name || payload.user.username)) || '';
    const triggerId = payload.trigger_id || '';
    const channel = (payload.channel && payload.channel.id) || (payload.container && payload.container.channel_id) || '';
    const msgTs   = (payload.message && payload.message.ts) || (payload.container && payload.container.message_ts) || '';

    return [{ json: {
      route: action.action_id, // 'confirm_ot' | 'open_form'
      codigo_ot: codigo,
      user_id: userId,
      user_name: userName,
      trigger_id: triggerId,
      channel: channel,
      message_ts: msgTs
    } }];
  }

  // ── Submit del modal ──
  if (payload.type === 'view_submission') {
    const view    = payload.view || {};
    const meta    = JSON.parse(view.private_metadata || '{}');
    const userId  = (payload.user && payload.user.id) || '';
    const userName= (payload.user && (payload.user.name || payload.user.username)) || '';
    const values  = (view.state && view.state.values) || {};

    // Helper para leer valor de un block
    const getVal = (block, action) => {
      const v = values[block] && values[block][action];
      if (!v) return null;
      if (v.type === 'static_select')      return v.selected_option ? v.selected_option.value : null;
      if (v.type === 'plain_text_input')   return v.value || null;
      if (v.type === 'number_input')       return v.value ? Number(v.value) : null;
      if (v.type === 'url_text_input')     return v.value || null;
      return v.value || null;
    };

    return [{ json: {
      route: 'form_submit',
      codigo_ot:     meta.codigo_ot,
      channel:       meta.channel,
      message_ts:    meta.message_ts,
      user_id:       userId,
      user_name:     userName,
      imputable_a:   getVal('imputable_a',   'val'),
      motivo_cierre: getVal('motivo_cierre', 'val'),
      cotizacion:    getVal('cotizacion',    'val'),
      comentarios:   getVal('comentarios',   'val'),
      link_customer: getVal('link_customer', 'val'),
      monto_cobro:   getVal('monto_cobro',   'val'),
      pipefy_id:     getVal('pipefy_id',     'val')
    } }];
  }
}

return [{ json: { route: 'ignore' } }];

// ── Procesa el click en "Confirmar propuesta" ──
const ev = $('Router Payload').first().json;
const ot = $input.first().json;

if (!ot || !ot.codigo_ot) {
  return [{ json: { skip: true, reason: 'OT no encontrada: ' + ev.codigo_ot } }];
}

const esc = s => String(s ?? '').replace(/'/g, "''");
const now = new Date().toISOString();

// Lógica de cierre:
// Si cotización != 'Sí' → caso completamente cerrado al confirmar
// Si cotización == 'Sí' → falta cobro + pipefy
const requiereCobro = (ot.cotizacion === 'Sí' || ot.cotizacion === 'Si');
const tienesCobro   = ot.monto_cobro != null && Number(ot.monto_cobro) > 0;
const tienesPipefy  = !!ot.pipefy_id;
const casoCerrado   = !requiereCobro || (tienesCobro && tienesPipefy);

const sql_update = `UPDATE "Oraculo_Opex".ot_clasificacion SET
  clasificacion_estado = 'confirmada',
  confirmed_at = '${now}',
  confirmed_by = '${esc(ev.user_id)}',
  caso_cerrado = ${casoCerrado}
WHERE codigo_ot = '${esc(ot.codigo_ot)}'`;

return [{ json: {
  skip: false,
  ot,
  ev,
  sql_update,
  caso_cerrado: casoCerrado,
  requiere_cobro: requiereCobro,
  action: 'confirm'
} }];

// ── Construye payload de views.open con el modal del formulario ──
const ev = $('Router Payload').first().json;
const ot = $input.first().json;

if (!ot || !ot.codigo_ot) {
  return [{ json: { skip: true, reason: 'OT no encontrada: ' + ev.codigo_ot } }];
}

// Opciones de los dropdowns
const opts = (arr) => arr.map(v => ({ text: { type: 'plain_text', text: v }, value: v }));
const imputableOpts = opts([
  'En revisión',
  'Externa imputable al OR',
  'Interna imputable a BIA',
  'Interna imputable al Cliente',
  'No imputable',
  'Se asume por servicio',
  'Factores externos'
]);
const motivoOpts = opts([
  'Atención a PQR',
  'Atención emergencia',
  'Cliente no gestionó permisos',
  'En revisión',
  'No se tenían los insumos',
  'Normalización de Telemedida Exitosa',
  'Revisión de la medida',
  'Verificación de consumo',
  'Generada por ops',
  'Retiro de equipos',
  'correo persona equivocada',
  'Equipo averiado',
  'Factores externos',
  'Desx/Recx remota'
]);
const cotizacionOpts = opts(['Sí', 'No', 'En revisión', 'N/A']);

// Encuentra la opción seleccionada (initial_option)
const initial = (list, val) => list.find(o => o.value === val) || null;

const blocks = [
  {
    type: 'section',
    text: { type: 'mrkdwn', text:
      '*OT:* `' + ot.codigo_ot + '` · *Servicio:* ' + (ot.tipo_de_servicio || '—') +
      ' · *Fase:* ' + (ot.fase_actual || '—')
    }
  },
  { type: 'divider' },
  {
    type: 'input',
    block_id: 'imputable_a',
    label: { type: 'plain_text', text: 'Imputable a' },
    element: Object.assign({
      type: 'static_select',
      action_id: 'val',
      options: imputableOpts
    }, initial(imputableOpts, ot.imputable_a) ? { initial_option: initial(imputableOpts, ot.imputable_a) } : {})
  },
  {
    type: 'input',
    block_id: 'motivo_cierre',
    label: { type: 'plain_text', text: 'Motivo de cierre' },
    element: Object.assign({
      type: 'static_select',
      action_id: 'val',
      options: motivoOpts
    }, initial(motivoOpts, ot.motivo_cierre) ? { initial_option: initial(motivoOpts, ot.motivo_cierre) } : {})
  },
  {
    type: 'input',
    block_id: 'cotizacion',
    label: { type: 'plain_text', text: '¿Hay cotización asumida por el cliente?' },
    element: Object.assign({
      type: 'static_select',
      action_id: 'val',
      options: cotizacionOpts
    }, initial(cotizacionOpts, ot.cotizacion) ? { initial_option: initial(cotizacionOpts, ot.cotizacion) } : {})
  },
  {
    type: 'input',
    block_id: 'comentarios',
    label: { type: 'plain_text', text: 'Comentarios' },
    element: {
      type: 'plain_text_input',
      action_id: 'val',
      multiline: true,
      max_length: 500,
      initial_value: (ot.comentarios || '').substring(0, 500)
    }
  },
  { type: 'divider' },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: '*Opcional — solo si aplica:*' }
  },
  {
    type: 'input',
    block_id: 'link_customer',
    optional: true,
    label: { type: 'plain_text', text: 'Link de Kustomer' },
    element: Object.assign({
      type: 'plain_text_input',
      action_id: 'val',
      placeholder: { type: 'plain_text', text: 'https://...' }
    }, ot.link_customer ? { initial_value: ot.link_customer } : {})
  },
  {
    type: 'input',
    block_id: 'monto_cobro',
    optional: true,
    label: { type: 'plain_text', text: 'Monto de cobro (COP, solo número)' },
    element: Object.assign({
      type: 'plain_text_input',
      action_id: 'val',
      placeholder: { type: 'plain_text', text: '500000' }
    }, ot.monto_cobro ? { initial_value: String(ot.monto_cobro) } : {})
  },
  {
    type: 'input',
    block_id: 'pipefy_id',
    optional: true,
    label: { type: 'plain_text', text: 'Pipefy ID' },
    element: Object.assign({
      type: 'plain_text_input',
      action_id: 'val',
      placeholder: { type: 'plain_text', text: '12345' }
    }, ot.pipefy_id ? { initial_value: ot.pipefy_id } : {})
  }
];

const modal = {
  trigger_id: ev.trigger_id,
  view: {
    type: 'modal',
    callback_id: 'cogs_form_submit',
    private_metadata: JSON.stringify({
      codigo_ot: ot.codigo_ot,
      channel: ev.channel,
      message_ts: ev.message_ts
    }),
    title:  { type: 'plain_text', text: 'OT ' + ot.codigo_ot.substring(0, 18) },
    submit: { type: 'plain_text', text: 'Guardar' },
    close:  { type: 'plain_text', text: 'Cancelar' },
    blocks: blocks
  }
};

return [{ json: { skip: false, modal_body: modal } }];

// ── Procesa el submit del formulario ──
const ev    = $('Router Payload').first().json;
const esc   = s => String(s ?? '').replace(/'/g, "''");
const now   = new Date().toISOString();
const code  = ev.codigo_ot;

const imputable     = ev.imputable_a;
const motivo        = ev.motivo_cierre;
const cotizacion    = ev.cotizacion;
const comentarios   = ev.comentarios;
const link_customer = ev.link_customer;
const monto_cobro   = ev.monto_cobro ? Number(String(ev.monto_cobro).replace(/[^0-9]/g, '')) : null;
const pipefy_id     = ev.pipefy_id;

// Lógica de cierre
const requiereCobro = (cotizacion === 'Sí' || cotizacion === 'Si');
const tienesCobro   = monto_cobro != null && monto_cobro > 0;
const tienesPipefy  = !!pipefy_id;
const casoCerrado   = !requiereCobro || (tienesCobro && tienesPipefy);

const sets = [
  "clasificacion_estado = 'corregida'",
  "confirmed_at = '" + now + "'",
  "confirmed_by = '" + esc(ev.user_id) + "'",
  "imputable_a = '" + esc(imputable) + "'",
  "motivo_cierre = '" + esc(motivo) + "'",
  "cotizacion = '" + esc(cotizacion) + "'",
  "comentarios = '" + esc(comentarios) + "'",
  "caso_cerrado = " + casoCerrado
];
if (link_customer)  sets.push("link_customer = '" + esc(link_customer) + "'");
if (monto_cobro)    sets.push("monto_cobro = " + monto_cobro);
if (pipefy_id)      sets.push("pipefy_id = '" + esc(pipefy_id) + "'");

const sql_update = "UPDATE \"Oraculo_Opex\".ot_clasificacion SET " + sets.join(', ') +
  " WHERE codigo_ot = '" + esc(code) + "'";

// GSheets update payload
const gsheets_update = {
  'codigo_ot': code,
  '¿Hay cotización asumida por el cliente?': cotizacion,
  'Imputable a': imputable,
  'Motivo de cierre': motivo,
  'Comentarios': comentarios
};
if (link_customer) gsheets_update['Link de kustomer'] = link_customer;
if (monto_cobro)   gsheets_update['Valor Ticket Pipefy'] = monto_cobro;
if (pipefy_id)     gsheets_update['Pipefy Finanzas'] = pipefy_id;

return [{ json: {
  sql_update,
  gsheets_update,
  codigo_ot: code,
  channel: ev.channel,
  message_ts: ev.message_ts,
  caso_cerrado: casoCerrado,
  requiere_cobro: requiereCobro,
  user_id: ev.user_id,
  action: 'form_submit'
} }];

// ── Reconstruye el mensaje original con check ☑️ o ✅ ──
// Lee el estado actual de la OT después del UPDATE y arma el header nuevo

const src = $('Process Confirm').first?.()?.json || $('Process Form Submit').first?.()?.json || $input.first().json;
const ot  = src.ot || {};
const code = src.codigo_ot || (ot && ot.codigo_ot) || '';
const channel = src.channel || src.ev?.channel || '';
const message_ts = src.message_ts || src.ev?.message_ts || '';
const userId = src.user_id || src.ev?.user_id || '';
const casoCerrado = src.caso_cerrado;
const requiereCobro = src.requiere_cobro;
const action = src.action;

// Header dinámico según estado
let header;
if (casoCerrado) {
  header = '✅ ' + code + ' — Cerrada';
} else if (requiereCobro) {
  header = '☑️ ' + code + ' — Clasificada · Falta cobro';
} else {
  header = '☑️ ' + code + ' — Clasificada';
}

// Texto del check al final
const userMention = userId ? '<@' + userId + '>' : 'usuario';
const verbo = action === 'confirm' ? 'Confirmada' : 'Diligenciada';

return [{ json: {
  channel,
  message_ts,
  new_header: header,
  user_mention: userMention,
  verbo,
  caso_cerrado: casoCerrado
} }];

// ── Construye el body de chat.update con el mensaje actualizado completo ──
const ot   = $input.first().json;
const meta = $('Build chat.update').first().json;
const code = ot.codigo_ot;

const fmtCOP = (n) => {
  if (n == null || isNaN(n)) return '—';
  return '$' + Number(n).toLocaleString('es-CO', {maximumFractionDigits:0});
};

const obs   = (ot.observacion_de_cierre || 'Sin observación').substring(0, 2800);
const razon = ot.razon_de_cierre || '—';

// Status row según estado
let statusLine;
if (meta.caso_cerrado) {
  statusLine = '*Estado:* ✅ Caso cerrado · ' + meta.verbo + ' por ' + meta.user_mention;
} else {
  statusLine = '*Estado:* ☑️ ' + meta.verbo + ' por ' + meta.user_mention + (ot.cotizacion === 'Sí' || ot.cotizacion === 'Si' ? ' · ⏳ Falta cobro / Pipefy' : '');
}

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: meta.new_header, emoji: true }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: statusLine }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: '*Servicio:* ' + (ot.tipo_de_servicio || '—') },
      { type: 'mrkdwn', text: '*Fase:* ' + (ot.fase_actual || '—') },
      { type: 'mrkdwn', text: '*Frontera:* ' + (ot.codigo_bia || '—') },
      { type: 'mrkdwn', text: '*Contratista:* ' + (ot.contratista || '—') },
      { type: 'mrkdwn', text: '*Costo:* ' + fmtCOP(ot.costo_total) },
      { type: 'mrkdwn', text: '*Cobro:* ' + (ot.monto_cobro ? fmtCOP(ot.monto_cobro) : '—') }
    ]
  },
  { type: 'divider' },
  {
    type: 'section',
    text: { type: 'mrkdwn', text:
      '*Clasificación final:*\n' +
      '• *Imputable a:* `' + (ot.imputable_a || '—') + '`\n' +
      '• *Motivo:* `' + (ot.motivo_cierre || '—') + '`\n' +
      '• *Cotización:* `' + (ot.cotizacion || '—') + '`\n' +
      '• *Pipefy:* `' + (ot.pipefy_id || '—') + '`\n\n' +
      '*Comentarios:* ' + (ot.comentarios || '—')
    }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: '*Observación original:*\n> ' + obs.replace(/\n/g, '\n> ') }
  }
];

// Si no está cerrado y requiere cobro → mostrar botón para diligenciar otra vez
if (!meta.caso_cerrado) {
  blocks.push({ type: 'divider' });
  blocks.push({
    type: 'actions',
    block_id: 'ot_actions',
    elements: [{
      type: 'button',
      text: { type: 'plain_text', text: '✏️ Actualizar / Agregar cobro' },
      action_id: 'open_form',
      value: code
    }]
  });
}

const body = {
  channel: meta.channel,
  ts: meta.message_ts,
  text: code + (meta.caso_cerrado ? ' — Cerrada' : ' — Clasificada'),
  blocks: blocks
};

return [{ json: { update_body: body } }];
